INSERT INTO site_settings (key, value, updated_at) VALUES
('page_privacy', '{"title":"Privacy Policy","body":"At FITNEXA, operated by Kesari Traders, we respect your privacy and are committed to protecting your personal information.\n\nWe may collect your name, contact details, delivery address, and order information to process orders, arrange delivery, provide customer support, and improve our services.\n\nWe do not sell or rent your personal information. Necessary information may be shared with trusted payment, logistics, installation, and service partners solely to provide our services.\n\nWe take reasonable measures to keep your information secure. By using our website, you agree to this Privacy Policy.\n\nPrivacy & Support: +91 75994 44073\n\nFITNEXA - Step Into Strength","seo_title":"","seo_description":""}', strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('page_terms', '{"title":"Terms & Conditions","body":"By using the FITNEXA website or purchasing our products, you agree to our terms. All orders are subject to stock availability and confirmation. Prices, specifications, and offers may change without prior notice. Delivery timelines are estimated and may vary. Warranty, installation, returns, replacements, and refunds are subject to the applicable product and company policies.\n\nFor assistance: +91 75994 44073\n\nFITNEXA | Kesari Traders\nStep Into Strength","seo_title":"","seo_description":""}', strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('page_shipping', '{"title":"Shipping Policy","body":"FITNEXA offers FREE Pan-India Delivery on every product.\n\nOrders are dispatched after confirmation, subject to product availability. Delivery timelines may vary depending on the location and logistics partner.\n\nFor shipping assistance: +91 75994 44073\n\nFITNEXA | Kesari Traders\nStep Into Strength","seo_title":"","seo_description":""}', strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('page_refund', '{"title":"Refund & Return Policy","body":"At FITNEXA, all sales are considered final once an order is confirmed. We do not accept returns or refunds for change of mind.\n\nIn case a product is received damaged, defective, or incorrect, please contact us promptly after delivery with relevant photos/videos. After verification, we will provide an appropriate resolution as per the applicable warranty/service terms.\n\nFor assistance: +91 75994 44073\n\nFITNEXA | Kesari Traders\nStep Into Strength","seo_title":"","seo_description":""}', strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('page_delivery', '{"title":"Pan-India Delivery","body":"FITNEXA offers FREE Pan-India Delivery on every product.\n\nOrders are dispatched after confirmation, subject to product availability. Delivery timelines may vary depending on the location and logistics partner.\n\nFor shipping assistance: +91 75994 44073\n\nFITNEXA | Kesari Traders\nStep Into Strength","seo_title":"","seo_description":""}', strftime('%Y-%m-%dT%H:%M:%fZ','now'))
